args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person (COALESCE(?bd1, ?bd2) AS ?birthDate) ?label WHERE {
  VALUES ?person { dbr:Patrick_Garcia dbr:Alfred_Wallis }
  OPTIONAL { ?person dbo:birthDate ?bd1 . }
  OPTIONAL { ?person dbp:birth_date ?bd2 . }
  OPTIONAL { ?person rdfs:label ?label . FILTER(langMatches(lang(?label), "en")) }
}
ORDER BY ?person

